digest.description:
.input {$included :integer}
.match $included
one {{The {$issue} issue of a Cyris digest: {$included} article selected from {$received}.}}
* {{The {$issue} issue of a Cyris digest: {$included} articles selected from {$received}.}}

issue.empty:
.input {$received :integer}
.match $received
one {{Nothing is in this issue: this run judged the {$received} article it received and kept none.}}
* {{Nothing is in this issue: this run judged the {$received} articles it received and kept none.}}

issue.empty_raw:
.input {$received :integer}
.match $received
one {{Nothing is in this issue: this run judged the {$received} article it received and kept none. {#link}All articles{/link} lists each one with its verdict.}}
* {{Nothing is in this issue: this run judged the {$received} articles it received and kept none. {#link}All articles{/link} lists each one with its verdict.}}

mail.empty_raw_at:
.input {$received :integer}
.match $received
one {{Nothing is in this issue: this run judged the {$received} article it received and kept none. All articles lists each one with its verdict: {$url}}}
* {{Nothing is in this issue: this run judged the {$received} articles it received and kept none. All articles lists each one with its verdict: {$url}}}

mail.kept:
.input {$received :integer}
.input {$sources :integer}
.match $received $sources
one one {{Kept {$included} of {$received} article from {$sources} source.}}
one * {{Kept {$included} of {$received} article from {$sources} sources.}}
* one {{Kept {$included} of {$received} articles from {$sources} source.}}
* * {{Kept {$included} of {$received} articles from {$sources} sources.}}

mail.stats:
.input {$sources :integer}
.match $sources
one {{{$sources} source · {$received} received · {#b}{$included} included{/b}}}
* {{{$sources} sources · {$received} received · {#b}{$included} included{/b}}}

notify.link_health:
.input {$synthetic :integer}
.input {$dead :integer}
.match $synthetic $dead
one one {{{$synthetic} newsletter issue fetched with no canonical link; {$dead} item in this digest has no link to follow}}
one * {{{$synthetic} newsletter issue fetched with no canonical link; {$dead} items in this digest have no link to follow}}
* one {{{$synthetic} newsletter issues fetched with no canonical link; {$dead} item in this digest has no link to follow}}
* * {{{$synthetic} newsletter issues fetched with no canonical link; {$dead} items in this digest have no link to follow}}

raw.label:
.input {$articles :integer}
.input {$sources :integer}
.match $articles $sources
one one {{All articles · {$articles} article · {$sources} source}}
one * {{All articles · {$articles} article · {$sources} sources}}
* one {{All articles · {$articles} articles · {$sources} source}}
* * {{All articles · {$articles} articles · {$sources} sources}}
